const body = $('Webhook').first().json.body;
const data = body.data;
const action = body.action || 'identity';
const options = body.options || {};

try {
  let result;

  switch (action) {
    case 'identity':
      result = data;
      break;

    case 'flatten':
      // Flatten nested object
      const flatten = (obj, prefix = '') => {
        return Object.keys(obj).reduce((acc, k) => {
          const pre = prefix.length ? prefix + (options.separator || '.') : '';
          if (typeof obj[k] === 'object' && obj[k] !== null && !Array.isArray(obj[k])) {
            Object.assign(acc, flatten(obj[k], pre + k));
          } else {
            acc[pre + k] = obj[k];
          }
          return acc;
        }, {});
      };
      result = flatten(data);
      break;

    case 'unflatten':
      // Unflatten to nested object
      const unflatten = (obj) => {
        const result = {};
        const sep = options.separator || '.';
        for (const key in obj) {
          const keys = key.split(sep);
          keys.reduce((acc, k, i) => {
            return acc[k] = (i === keys.length - 1) ? obj[key] : (acc[k] || {});
          }, result);
        }
        return result;
      };
      result = unflatten(data);
      break;

    case 'pick':
      // Pick specific keys
      const keys = options.keys || [];
      result = keys.reduce((acc, k) => {
        if (k in data) acc[k] = data[k];
        return acc;
      }, {});
      break;

    case 'omit':
      // Omit specific keys
      const omitKeys = options.keys || [];
      result = Object.keys(data).reduce((acc, k) => {
        if (!omitKeys.includes(k)) acc[k] = data[k];
        return acc;
      }, {});
      break;

    case 'rename':
      // Rename keys
      const mapping = options.mapping || {};
      result = Object.keys(data).reduce((acc, k) => {
        const newKey = mapping[k] || k;
        acc[newKey] = data[k];
        return acc;
      }, {});
      break;

    case 'filter':
      // Filter array by condition
      if (!Array.isArray(data)) {
        throw new Error('filter action requires array data');
      }
      const filterKey = options.key;
      const filterValue = options.value;
      const filterOp = options.operator || 'eq';
      result = data.filter(item => {
        const val = item[filterKey];
        switch (filterOp) {
          case 'eq': return val === filterValue;
          case 'neq': return val !== filterValue;
          case 'gt': return val > filterValue;
          case 'gte': return val >= filterValue;
          case 'lt': return val < filterValue;
          case 'lte': return val <= filterValue;
          case 'contains': return String(val).includes(filterValue);
          case 'startsWith': return String(val).startsWith(filterValue);
          case 'endsWith': return String(val).endsWith(filterValue);
          default: return true;
        }
      });
      break;

    case 'sort':
      // Sort array
      if (!Array.isArray(data)) {
        throw new Error('sort action requires array data');
      }
      const sortKey = options.key;
      const sortOrder = options.order || 'asc';
      result = [...data].sort((a, b) => {
        const aVal = sortKey ? a[sortKey] : a;
        const bVal = sortKey ? b[sortKey] : b;
        const cmp = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
        return sortOrder === 'desc' ? -cmp : cmp;
      });
      break;

    case 'group':
      // Group array by key
      if (!Array.isArray(data)) {
        throw new Error('group action requires array data');
      }
      const groupKey = options.key;
      result = data.reduce((acc, item) => {
        const key = item[groupKey];
        if (!acc[key]) acc[key] = [];
        acc[key].push(item);
        return acc;
      }, {});
      break;

    case 'map':
      // Map array with template
      if (!Array.isArray(data)) {
        throw new Error('map action requires array data');
      }
      const template = options.template || {};
      result = data.map(item => {
        return Object.keys(template).reduce((acc, k) => {
          const path = template[k];
          acc[k] = path.split('.').reduce((o, p) => o?.[p], item);
          return acc;
        }, {});
      });
      break;

    case 'merge':
      // Merge with another object
      const mergeWith = options.with || {};
      result = { ...data, ...mergeWith };
      break;

    case 'to_array':
      // Convert object to array of {key, value}
      result = Object.entries(data).map(([key, value]) => ({ key, value }));
      break;

    case 'to_object':
      // Convert array of {key, value} to object
      if (!Array.isArray(data)) {
        throw new Error('to_object action requires array data');
      }
      const keyField = options.key_field || 'key';
      const valueField = options.value_field || 'value';
      result = data.reduce((acc, item) => {
        acc[item[keyField]] = item[valueField];
        return acc;
      }, {});
      break;

    default:
      throw new Error(`Unknown action: ${action}`);
  }

  return [{
    json: {
      success: true,
      data: {
        result: result,
        action: action,
        input_type: Array.isArray(data) ? 'array' : typeof data,
        output_type: Array.isArray(result) ? 'array' : typeof result
      },
      meta: { provider: 'json-transformer' }
    }
  }];

} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 400,
        message: e.message,
        status: 'TRANSFORM_ERROR'
      },
      meta: { provider: 'json-transformer' }
    }
  }];
}
